cheduler; // to control your personal task\n\nvoid sendMessage(); // Prototype\n\n// Define a task to send messages every 1 second\nTask taskSendMessage(1000, TASK_FOREVER, &sendMessage);\n\nvoid sendMessage() {\n    String msg = "Hello from node ";\n    msg += mesh.getNodeId();\n    mesh.sendBroadcast(msg);\n    Serial.printf("Sent broadcast: %s\\n", msg.c_str());\n}\n\n// Callback: When a message is received\nvoid receivedCallback( uint32_t from, String &msg ) {\n    Serial.printf("Received from %u msg=%s\\n", from, msg.c_str());\n}\n\n// Callback: When a new connection is established\nvoid newConnectionCallback(uint32_t nodeId) {\n    Serial.printf("New Connection, nodeId = %u\\n", nodeId);\n}\n\n// Callback: When connection changes\nvoid changedConnectionCallback() {\n    Serial.printf("Changed connections\\n");\n}\n\n// Callback: Time adjustment\nvoid nodeTimeAdjustedCallback(int32_t offset) {\n    Serial.printf("Adjusted time %u. Offset = %d\\n", mesh.getNodeTime(), offset);\n}\n\nvoid setup() {\n    Serial.begin(115200);\n\n    // Debug messages\n    mesh.setDebugMsgTypes( ERROR | STARTUP );  \n\n    // Initialize Mesh\n    mesh.init( MESH_PREFIX, MESH_PASSWORD, &userScheduler, MESH_PORT );\n\n    // Register Callbacks\n    mesh.onReceive(&receivedCallback);\n    mesh.onNewConnection(&newConnectionCallback);\n    mesh.onChangedConnections(&changedConnectionCallback);\n    mesh.onNodeTimeAdjusted(&nodeTimeAdjustedCallback);\n\n    // Add task to scheduler\n    userScheduler.addTask( taskSendMessage );\n    taskSendMessage.enable();\n}\n\nvoid loop() {\n    // Keep the mesh network running\n    mesh.update();\n}\n'})}),"\n",(0,l.jsx)(e.h4,{id:"\u52B9\u679C\u306E\u78BA\u8A8D-2",children:"\u52B9\u679C\u306E\u78BA\u8A8D"}),"\n",(0,l.jsxs)(e.ul,{children:["\n",(0,l.jsx)(e.li,{children:"2 \u53F0\u306E XIAO ESP32-C5 \u30C7\u30D0\u30A4\u30B9\u306B\u30B3\u30FC\u30C9\u3092\u66F8\u304D\u8FBC\u307F\u3001\u4EFB\u610F\u306E\u30B7\u30EA\u30A2\u30EB\u30DD\u30FC\u30C8\u30C4\u3